<script setup lang="ts">
// 六膳门 · 生产总览「在制品」视图（BL-borrow 10）与「效率」视图（BL-borrow 15）。只读黑湖快照；标准工时是 Cretas 补充。
// 在制：工单 × 工序矩阵。工序列按产品工艺路线的步骤顺序合并（不手工勾选）；格子 = 该工单在该工序的已批准良品 / 任务计划量与状态；
//      「停在」= 第一个未完成的已记录工序。只看执行中的工单（可切全部）。
// 效率：按工序汇总标准工时、有效工时、实际效率、达标率；没有标准显示「无标准」并给「补充标准」入口，不给达标率。只到工序，不做个人排名。
import {computed,onMounted,ref} from 'vue'
import UButton from '@nuxt/ui/components/Button.vue'
import type {Row} from '../frame/types'
import {S,rs,rowId,navigate} from '../frame/store'
import {fmtNumber,fmtPct,fmtQty,sourceTagHTML,openFormula,confirmReason} from '../frame/ai-protocol'
import {processEfficiency,RULE,type Standard,type TaskInput} from './efficiency'
import {acceptanceSession} from './session'
import {bjTime} from './time'
const tab=ref<'wip'|'eff'>(S.query.get('tab')==='eff'?'eff':'wip'),onlyRunning=ref(true),q=ref('')
const session=acceptanceSession()
const aq=(path:string)=>{const p=new URLSearchParams({ws:'lsm'});if(session)p.set('acceptanceSession',session);return '/__unified/a/api/'+path+'?'+p}
const standards=ref<Standard[]>([]),stdVersion=ref(0),err=ref(''),notice=ref(''),edit=ref<{code:string;name:string;unit:string}|null>(null),secs=ref(''),unit=ref(''),reason=ref(''),busy=ref(false)
const procById=(id:unknown)=>rs('process').find(p=>String(p.id)===String(id))
// 工序列顺序：各路线步骤 seq 合并，按最早出现的位置排序；不在任何路线里的工序排在后面
const columns=computed(()=>{const pos=new Map<string,number>();for(const r of rs('routing')){const steps=Array.isArray(r.processRoutingSteps)?r.processRoutingSteps as Row[]:[];steps.forEach((s,i)=>{const c=String(s.code);pos.set(c,Math.min(pos.get(c)??999,Number(s.seq??i+1)))})}
  const used=new Set(rs('task').map(t=>String(procById(t.processId)?.code||'')).filter(Boolean))
  return [...used].sort((a,b)=>(pos.get(a)??999)-(pos.get(b)??999)||a.localeCompare(b)).map(c=>({code:c,name:String(rs('process').find(p=>p.code===c)?.name||c),inRoute:pos.has(c)}))})
const orders=computed(()=>rs('project').filter(p=>(!onlyRunning.value||String(p.status)==='10')&&(!q.value||[p.projectCode,p.productName].some(v=>String(v??'').includes(q.value)))).map(p=>{const tasks=rs('task').filter(t=>String(t.projectId)===rowId(p));const cells=new Map<string,Row[]>();for(const t of tasks){const c=String(procById(t.processId)?.code||'');if(!cells.has(c))cells.set(c,[]);cells.get(c)!.push(t)}
  const stuck=columns.value.find(col=>(cells.get(col.code)||[]).some(t=>String(t.processStatus)!=='20'))
  return {p,cells,stuck:stuck?stuck.name:tasks.length?'已全部完成':'来源未返回任务'}}))
const cellState=(ts:Row[]|undefined)=>!ts||!ts.length?'':ts.every(t=>String(t.processStatus)==='20')?'done':ts.some(t=>String(t.processStatus)==='10')?'run':'todo'
const cellText=(ts:Row[]|undefined,unit:string)=>{if(!ts||!ts.length)return '';const a=ts.reduce((s,t)=>s+(Number(t.approvedFineAmount)||0),0),pl=ts.reduce((s,t)=>s+(Number(t.planAmount)||0),0);return fmtNumber(a)+' / '+fmtNumber(pl)+(unit?'':'')}
const bottleneck=computed(()=>{const m=new Map<string,number>();for(const o of orders.value)if(!['已全部完成','来源未返回任务'].includes(o.stuck))m.set(o.stuck,(m.get(o.stuck)||0)+1);return [...m.entries()].sort((a,b)=>b[1]-a[1]).slice(0,3)})
// ---- 效率 ----
const taskInputs=computed<TaskInput[]>(()=>rs('task').map(t=>{const proc=procById(t.processId);const unit=rs('output').find(o=>String(o.taskId)===String(t.id))?.stockUnit;const g=t.approvedFineAmount;const e=t.sumEffectiveTime;return {taskId:String(t.id),processCode:String(proc?.code||''),processName:String(proc?.name||t.processName||''),good:g===null||g===undefined||g===''?null:Number(g),unit:unit?String(unit):null,effectiveSeconds:e===null||e===undefined||e===''?null:Number(e)}}))
const eff=computed(()=>processEfficiency(taskInputs.value,standards.value).sort((a,b)=>(columns.value.findIndex(c=>c.code===a.processCode))-(columns.value.findIndex(c=>c.code===b.processCode))))
const hours=(s:number|null)=>s===null?'—':fmtNumber(s/3600)+' h'
async function loadStd(){err.value='';try{const r=await (await fetch(aq('standards'))).json();if(!r.success)throw Error(r.message==='未找到'?'标准工时服务尚未接入统一入口':r.message);standards.value=r.data.standards;stdVersion.value=r.data.version}catch(e){err.value=e instanceof Error?e.message:'读取标准失败'}}
function openEdit(code:string,name:string){const u=taskInputs.value.find(t=>t.processCode===code&&t.unit)?.unit||'';const cur=standards.value.find(s=>s.processCode===code&&!s.revoked);edit.value={code,name,unit:u};secs.value=cur?String(cur.secondsPerUnit):'';unit.value=cur?.unit||u;reason.value='';notice.value=''}
async function saveStd(){if(!edit.value)return;busy.value=true;err.value='';try{const r=await fetch(aq('standards/save'),{method:'POST',headers:{'content-type':'application/json','x-prototype-action':'explicit'},body:JSON.stringify({ws:'lsm',processCode:edit.value.code,secondsPerUnit:Number(secs.value),unit:unit.value,reason:reason.value,expectedVersion:stdVersion.value})});const b=await r.json();if(!r.ok||!b.success)throw Error(b.message||'保存失败');await loadStd();const s=standards.value.find(x=>x.processCode===edit.value!.code&&!x.revoked);notice.value=s?'已保存并回读：'+edit.value.name+' 标准 '+s.secondsPerUnit+' 秒/'+s.unit:'已保存，但回读没找到，请刷新核对';edit.value=null}catch(e){err.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}}
async function revokeStd(id:string){const why=await confirmReason({title:'撤销标准工时',object:'标准 '+id,message:'撤销后保留留痕，可在记录里看到原因；不回写黑湖。',reasonLabel:'撤销原因',okLabel:'确认撤销',danger:true,required:true});if(!why)return;busy.value=true;try{const r=await fetch(aq('standards/revoke'),{method:'POST',headers:{'content-type':'application/json','x-prototype-action':'explicit'},body:JSON.stringify({ws:'lsm',id,reason:why,expectedVersion:stdVersion.value})});const b=await r.json();if(!r.ok||!b.success)throw Error(b.message||'撤销失败');await loadStd();notice.value='已撤销，留痕保留；该工序恢复「无标准」。'}catch(e){err.value=e instanceof Error?e.message:'撤销失败'}finally{busy.value=false}}
// ---- 第四批 BL 26：报工时段规则（Cretas 补充）与「有效工时（按班次规则）」 ----
interface Shift{name:string;start:string;end:string;breaks:{start:string;end:string}[]}
interface Rule{id:string;shifts:Shift[];source:string;at:string;reason:string}
interface Hour{reportId:string;taskId:string;status:string;totalSeconds?:number;breakSeconds?:number;overtimeSeconds?:number;effectiveSeconds?:number;inShiftSeconds?:number}
const rule=ref<Rule|null>(null),ruleVersion=ref(0),hoursRows=ref<Hour[]>([]),formula=ref(''),ruleEdit=ref(false),ruleText=ref(''),ruleReason=ref(''),ruleErr=ref('')
async function loadShift(){try{const [r,h]=await Promise.all([fetch(aq('shift-rules')).then(x=>x.json()),fetch(aq('shift-hours')).then(x=>x.json())]);if(!r.success)throw Error(r.message==='未找到'?'班次规则服务尚未接入统一入口':r.message);rule.value=r.data.rule;ruleVersion.value=r.data.version;stdVersion.value=r.data.version;hoursRows.value=h.data?.rows||[];formula.value=(h.data?.formula||'')+(h.data?.timeBasis?'；'+h.data.timeBasis:'')}catch(e){ruleErr.value=e instanceof Error?e.message:'读取班次规则失败'}}
// 每个工序：把该工序任务的报工按班次规则汇总；不能计算的报工单独计数并写原因
const taskProc=computed(()=>new Map(rs('task').map(t=>[String(t.id),String(procById(t.processId)?.code||'')])))
const shiftByProc=computed(()=>{const m=new Map<string,{eff:number;brk:number;ot:number;inShift:number;n:number;bad:Record<string,number>}>();for(const h of hoursRows.value){const code=taskProc.value.get(h.taskId)||'';if(!m.has(code))m.set(code,{eff:0,brk:0,ot:0,inShift:0,n:0,bad:{}});const x=m.get(code)!;if(h.status==='已计算'){x.eff+=h.effectiveSeconds||0;x.brk+=h.breakSeconds||0;x.ot+=h.overtimeSeconds||0;x.inShift+=h.inShiftSeconds||0;x.n++}else x.bad[h.status]=(x.bad[h.status]||0)+1}return m})
// 黑湖原工时：该工序全部任务的 sumEffectiveTime 合计，与「按班次规则」并列，不依赖有没有标准
const blackByProc=computed(()=>{const m=new Map<string,number>();for(const t of taskInputs.value)if(t.effectiveSeconds!==null)m.set(t.processCode,(m.get(t.processCode)||0)+t.effectiveSeconds);return m})
const blackHours=(code:string)=>blackByProc.value.has(code)?hours(blackByProc.value.get(code)!):'黑湖未返回'
function ruleCell(code:string){const x=shiftByProc.value.get(code);if(!rule.value)return '未配置班次规则';if(!x||!x.n)return x&&Object.keys(x.bad).length?'无法计算（'+Object.entries(x.bad).map(([k,v])=>k+' '+v).join('；')+'）':'无报工';return hours(x.eff)}
function showFormula(ev:Event,code:string,name:string){const x=shiftByProc.value.get(code);openFormula(ev.currentTarget as HTMLElement,{title:name+' · 有效工时（按班次规则）',// 第四批审计退回 1：传未舍入的小时数，由弹层统一格式化；否则两项各自舍入后相加会差 0.01，被误报「不一致」
  result:{value:x&&x.n?x.eff/3600:null,unit:'h'},plus:x?[{label:'班内工作（已扣休息）',value:x.inShift/3600,unit:'h',source:'cretas'},{label:'班外时长（记为加班）',value:x.ot/3600,unit:'h',source:'cretas'}]:[],minus:[],formula:formula.value||'有效工时 = 报工总时长 − 班次内休息',note:'按 '+(x?.n||0)+' 条有起止时间的报工计算'+(x&&Object.keys(x.bad).length?'；未计入：'+Object.entries(x.bad).map(([k,v])=>k+' '+v+' 条').join('；'):'')+'。班次规则是 Cretas 补充；黑湖「有效工时」原值在左侧并列，不被替换。'})}
function shiftsToText(r:Rule|null){return (r?.shifts||[{name:'白班',start:'08:00',end:'17:00',breaks:[{start:'12:00',end:'13:00'}]}]).map(x=>x.name+' '+x.start+'-'+x.end+(x.breaks.length?' 休息 '+x.breaks.map(b=>b.start+'-'+b.end).join(','):'')).join('\n')}
function parseShifts(t:string):Shift[]{return t.split('\n').map(l=>l.trim()).filter(Boolean).map(l=>{const m=/^(\S+)\s+(\d\d:\d\d)-(\d\d:\d\d)(?:\s+休息\s+(.+))?$/.exec(l);if(!m)throw Error('格式应为「班次名 HH:MM-HH:MM 休息 HH:MM-HH:MM,HH:MM-HH:MM」：'+l);return {name:m[1],start:m[2],end:m[3],breaks:(m[4]||'').split(/[,，]/).map(x=>x.trim()).filter(Boolean).map(x=>{const k=/^(\d\d:\d\d)-(\d\d:\d\d)$/.exec(x);if(!k)throw Error('休息时段格式应为 HH:MM-HH:MM：'+x);return {start:k[1],end:k[2]}})}})}
function openRule(){ruleText.value=shiftsToText(rule.value);ruleReason.value='';ruleErr.value='';ruleEdit.value=true}
async function saveRule(){ruleErr.value='';let shifts:Shift[];try{shifts=parseShifts(ruleText.value)}catch(e){ruleErr.value=e instanceof Error?e.message:'格式错误';return}busy.value=true;try{const r=await fetch(aq('shift-rules/save'),{method:'POST',headers:{'content-type':'application/json','x-prototype-action':'explicit'},body:JSON.stringify({ws:'lsm',shifts,reason:ruleReason.value,expectedVersion:ruleVersion.value})});const b=await r.json();if(!r.ok||!b.success)throw Error(b.message||'保存失败');await loadShift();await loadStd();ruleEdit.value=false;notice.value=rule.value?'班次规则已保存并回读：'+rule.value.shifts.map(x=>x.name+' '+x.start+'-'+x.end).join('、'):'已保存，但回读没找到，请刷新核对'}catch(e){ruleErr.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}}
async function revokeRule(){if(!rule.value)return;const why=await confirmReason({title:'撤销班次规则',object:rule.value.shifts.map(x=>x.name+' '+x.start+'-'+x.end).join('；'),message:'撤销后保留留痕，可在记录里看到原因；不回写黑湖。',reasonLabel:'撤销原因',okLabel:'确认撤销',danger:true,required:true});if(!why)return;busy.value=true;try{const r=await fetch(aq('shift-rules/revoke'),{method:'POST',headers:{'content-type':'application/json','x-prototype-action':'explicit'},body:JSON.stringify({ws:'lsm',id:rule.value.id,reason:why,expectedVersion:ruleVersion.value})});const b=await r.json();if(!r.ok||!b.success)throw Error(b.message||'撤销失败');await loadShift();await loadStd();notice.value='班次规则已撤销，留痕保留；有效工时（按班次规则）恢复为「未配置班次规则」。'}catch(e){ruleErr.value=e instanceof Error?e.message:'撤销失败'}finally{busy.value=false}}
onMounted(()=>{loadStd();loadShift()})
</script>
<template><section class="card table-panel wip">
<div class="wip-head"><nav class="cs-tabs" role="tablist"><button role="tab" :aria-selected="tab==='wip'" @click="tab='wip'">在制品（工序 × 工单）</button><button role="tab" :aria-selected="tab==='eff'" @click="tab='eff'">效率与达标率</button></nav><span v-html="sourceTagHTML('blacklake')"/></div>
<template v-if="tab==='wip'">
<form class="filters" @submit.prevent><input v-model="q" aria-label="搜索工单" placeholder="工单号、产品"><label><input v-model="onlyRunning" type="checkbox"> 只看执行中</label></form>
<p class="wip-note">格子 = 该工序已批准良品 / 任务计划量；颜色：完成、进行中、未开始。「停在」是第一个没完成的已记录工序。工序顺序取各产品工艺路线的步骤顺序。<b v-if="bottleneck.length">当前堵点：{{bottleneck.map(([n,c])=>n+' '+c+' 张').join('、')}}</b></p>
<div class="table-scroll"><table><thead><tr><th class="sticky">工单</th><th>产品</th><th>停在</th><th v-for="c in columns" :key="c.code" :title="c.code+(c.inRoute?'':'（不在任何当前路线里）')">{{c.name}}</th></tr></thead><tbody>
<tr v-for="o in orders" :key="rowId(o.p)"><td class="sticky"><a href="#" @click.prevent="navigate('/production/plans',{project:rowId(o.p)})">{{o.p.projectCode}}</a></td><td>{{o.p.productName}}</td><td><b>{{o.stuck}}</b></td><td v-for="c in columns" :key="c.code" :class="'c-'+cellState(o.cells.get(c.code))" :title="(o.cells.get(c.code)||[]).map(t=>'任务 '+t.id).join('、')">{{cellText(o.cells.get(c.code),String(o.p.projectUnit||''))}}</td></tr>
<tr v-if="!orders.length"><td :colspan="columns.length+3" class="empty">当前筛选没有工单。</td></tr></tbody></table></div>
</template>
<template v-else>
<p class="wip-note">{{RULE}}。标准工时是 Cretas 补充（黑湖没有这个字段），补充值不回写黑湖；只到工序，不做个人排名。<span v-html="sourceTagHTML('cretas')"/></p>
<p v-if="err" role="alert" class="wip-err">{{err}}</p><p v-if="notice" role="status" class="wip-ok">{{notice}}</p>
<div class="rule-panel"><b>报工时段规则</b> <span v-html="sourceTagHTML('cretas')"/> <span v-if="rule">{{rule.shifts.map(x=>x.name+' '+x.start+'–'+x.end+(x.breaks.length?'（休息 '+x.breaks.map(b=>b.start+'–'+b.end).join('、')+'）':'')).join('；')}} · {{bjTime(rule.at)}} · 原因：{{rule.reason}}</span><span v-else class="muted">未配置。配置后按班次算每条报工的有效工时、休息与班外（加班）；黑湖原工时不变。</span>
<UButton size="xs" color="neutral" variant="outline" @click="openRule">{{rule?'修改班次':'配置班次'}}</UButton><UButton v-if="rule" size="xs" color="error" variant="ghost" :loading="busy" @click="revokeRule">撤销</UButton><p v-if="ruleErr" class="wip-err">{{ruleErr}}</p>
<div v-if="ruleEdit" class="wip-edit"><label class="grow">每行一个班次：<textarea v-model="ruleText" rows="3" aria-label="班次规则" placeholder="白班 08:00-17:00 休息 12:00-13:00"/></label><label>原因 <input v-model="ruleReason" aria-label="班次规则原因" placeholder="例如：按车间排班表"></label><p class="muted">保存前：{{rule?shiftsToText(rule).replace(/\n/g,'；'):'未配置'}}；保存后：{{ruleText.replace(/\n/g,'；')||'—'}}。夜班下班早于上班按次日算；不做拖拽配置。</p><div class="actions"><UButton size="sm" color="neutral" variant="ghost" @click="ruleEdit=false">取消</UButton><UButton size="sm" :loading="busy" :disabled="!ruleText.trim()||!ruleReason.trim()" @click="saveRule">确认保存</UButton></div></div></div>
<div class="table-scroll"><table><thead><tr><th>工序</th><th>标准（秒/单位）</th><th>任务</th><th>可计算</th><th>标准工时</th><th>有效工时（黑湖）</th><th>有效工时（按班次规则）</th><th>实际效率</th><th>达标率</th><th>说明</th><th class="op">操作</th></tr></thead><tbody>
<tr v-for="e in eff" :key="e.processCode"><td>{{e.processName}}<small>{{e.processCode}}</small></td><td>{{e.standard?fmtNumber(e.standard.secondsPerUnit)+' / '+e.standard.unit:'无标准'}}</td><td>{{e.tasks}}</td><td>{{e.computable}}</td><td>{{hours(e.totalStandardSeconds)}}</td><td :title="'黑湖任务 sumEffectiveTime 合计（全部任务，不论有没有标准）；有标准时参与效率计算的是其中 '+e.computable+' 个任务'">{{blackHours(e.processCode)}}</td><td class="rule-cell">{{ruleCell(e.processCode)}} <button type="button" class="formula-btn" aria-label="口径" title="口径：怎么算出来的" @click="showFormula($event,e.processCode,e.processName)">ƒ</button></td><td>{{e.efficiency===null?'—':fmtPct(e.efficiency*100)}}</td><td>{{e.rate===null?'—':fmtPct(e.rate*100)+'（'+e.reached+'/'+e.computable+'）'}}</td><td class="muted">{{e.note}}</td><td class="op"><UButton size="xs" color="neutral" variant="ghost" @click="openEdit(e.processCode,e.processName)">{{e.standard?'修改标准':'补充标准'}}</UButton><UButton v-if="e.standard" size="xs" color="error" variant="ghost" :loading="busy" @click="revokeStd(e.standard.id)">撤销</UButton></td></tr></tbody></table></div>
<div v-if="edit" class="wip-edit"><b>{{edit.name}}（{{edit.code}}）标准工时 · Cretas 补充</b><label>标准秒/单位 <input v-model="secs" type="number" min="0" step="any" aria-label="标准秒每单位"></label><label>单位 <input v-model="unit" aria-label="标准单位"></label><label>原因 <input v-model="reason" placeholder="例如：按车间工艺卡" aria-label="补充原因"></label><p class="muted">保存前：{{standards.find(s=>s.processCode===edit!.code&&!s.revoked)?.secondsPerUnit??'无标准'}}；保存后：{{secs||'—'}} 秒/{{unit||'—'}}。单位必须和报工单位一致，否则该工序显示「单位不一致」。</p><div class="actions"><UButton size="sm" color="neutral" variant="ghost" @click="edit=null">取消</UButton><UButton size="sm" :loading="busy" :disabled="!(Number(secs)>0)||!unit||!reason.trim()" @click="saveStd">确认保存</UButton></div></div>
</template>
</section></template>
<style scoped>
.wip-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}.wip-note{font-size:12px;color:#667589;margin:4px 0 8px}.wip-err{color:var(--cs-danger,#c53b3b);font-size:13px}.wip-ok{color:var(--cs-success,#2f7d4a);font-size:13px}
.table-scroll td,.table-scroll th{white-space:nowrap;height:32px;font-variant-numeric:tabular-nums}.table-scroll small{display:block;color:#8a96a6;font-size:11px}.sticky{position:sticky;left:0;background:var(--cs-surface,#fff);z-index:1}
.c-done{background:var(--cs-success-soft,#eaf6ee)}.c-run{background:var(--cs-warning-soft,#fff5e6)}.c-todo{background:#f0f2f5}.muted{color:#748297;font-size:12px}.rule-panel{margin:8px 0;padding:8px 12px;border:1px solid var(--cs-border,#e3e8ef);border-radius:8px;font-size:13px;display:flex;flex-wrap:wrap;gap:8px;align-items:center}.rule-panel .wip-edit{flex-basis:100%}.wip-edit .grow{flex:1 1 360px}.wip-edit textarea{width:100%;border:1px solid var(--cs-border,#d6dee7);border-radius:6px;padding:4px 8px;font-family:inherit}.formula-btn{border:1px solid var(--cs-border,#d6dee7);border-radius:4px;background:#fff;font-size:11px;padding:0 5px;cursor:pointer}
